      es: ["Capacidad instalada: 120 MW.", "Número de turbinas: 3.", "Altura de la presa: 30 metros.", "Longitud de la presa: 500 metros.", "Coste de construcción: 300 millones de dólares.", "Puesta en servicio: 2014."],
      pt: ["Capacidade instalada: 120 MW.", "Número de turbinas: 3.", "Altura da barragem: 30 metros.", "Comprimento da barragem: 500 metros.", "Custo de construção: 300 milhões de dólares.", "Colocação em funcionamento: 2014."],
      fr: ["Puissance installée : 120 MW.", "Nombre de turbines : 3.", "Hauteur du barrage : 30 mètres.", "Longueur du barrage : 500 mètres.", "Coût de construction : 300 millions de dollars US.", "Mise en service : 2014."],
